import React, { useState, useContext } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import { AuthContext } from "../contexts/AuthContext";

export default function Login() {
  const navigate = useNavigate();
  const { login } = useContext(AuthContext);
  const [form, setForm] = useState({ email: "", password: "", totp: "" });
  const [error, setError] = useState("");

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");

    try {
      const res = await axios.post("http://localhost:4000/api/auth/login", form);
      const { token, user } = res.data;

      if (!user || !token) {
        setError("Invalid response from server");
        return;
      }

      // Login successful
      login({ token, user });

      // Redirect based on role
      if (user.role === "student") navigate("/student-dashboard"); 
      else if (user.role === "admin") navigate("/admin-dashboard");
      else if (user.role === "comelec") navigate("/comelec-dashboard");

    } catch (err) {
      console.error(err);
      setError(err.response?.data?.error || "Login failed. Please try again.");
    }
  };

  return (
    <div style={{ display: "flex", justifyContent: "center", padding: "50px", fontFamily: "Arial, sans-serif" }}>
      <div style={{ width: "400px", padding: "30px", border: "1px solid #ddd", borderRadius: "10px", boxShadow: "0 4px 10px rgba(0,0,0,0.1)" }}>
        <h2 style={{ textAlign: "center", marginBottom: "20px", color: "#333" }}>Login</h2>

        <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
          <input
            type="email"
            name="email"
            placeholder="Email"
            value={form.email}
            onChange={handleChange}
            required
            style={{ padding: "10px", borderRadius: "5px", border: "1px solid #ccc" }}
          />
          <input
            type="password"
            name="password"
            placeholder="Password"
            value={form.password}
            onChange={handleChange}
            required
            style={{ padding: "10px", borderRadius: "5px", border: "1px solid #ccc" }}
          />
          <input
            type="text"
            name="totp"
            placeholder="Enter OTP (if student)"
            value={form.totp}
            onChange={handleChange}
            style={{ padding: "10px", borderRadius: "5px", border: "1px solid #ccc" }}
          />
          <button type="submit" style={{ padding: "12px", borderRadius: "5px", border: "none", backgroundColor: "#007bff", color: "#fff", fontWeight: "bold", cursor: "pointer" }}>
            Login
          </button>
        </form>

        {error && <p style={{ marginTop: "20px", textAlign: "center", color: "red" }}>{error}</p>}

        <p style={{ marginTop: "20px", textAlign: "center", color: "#555" }}>
          Don't have an account?{" "}
          <button
            type="button"
            style={{ color: "#007bff", fontWeight: "bold", cursor: "pointer", background: "none", border: "none", padding: 0 }}
            onClick={() => navigate("/register")}
          >
            Register
          </button>
        </p>
      </div>
    </div>
  );
}
